  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 13, $j$4.1 The Informative Speech$j$, $j${"readings": [{"title": "Nehemiah 8 (King James Version)", "url": "/portal/bible/Nehemiah/8"}], "body": "An informative speech teaches. It helps listeners understand something new or see something familiar in a fresh way. Nehemiah 8:8 describes a great public teaching: So they read in the book in the law of God distinctly, and gave the sense, and caused them to understand the reading. Reading clearly, giving the sense and causing understanding are the goals of every informative speaker.\n\nInformative speeches fall into several kinds. A speech about objects describes things, such as a telescope or a hurricane shelter. A speech about people tells the life and work of a person, such as a nurse, a missionary or a scientist. A speech about events explains what happened, such as a historic storm or a school festival. A speech about processes explains how something is done or how it works, such as how to change a tire or how a bill becomes a law. A speech about concepts explains ideas, such as freedom, honesty or supply and demand.\n\nTo inform well, keep these principles in mind. Be clear. Use simple words, define terms and avoid jargon the audience may not know. Be organized. Choose a pattern that fits the topic, such as chronological order for a process or topical order for categories. Be concrete. Use examples, stories, comparisons and visuals so that ideas can be seen. Move from the known to the unknown, and connect the new idea to something the audience already understands, such as comparing the heart to a pump. Limit the number of main points so that listeners can remember them, and repeat key ideas. Make the topic relevant, by showing why it matters to the audience. Be accurate and cite sources. Do not try to persuade in an informative speech. Present the facts fairly and let listeners decide what to do with them.\n\nA demonstration speech is a special type that shows how to do something. Plan the steps in order, practice with every tool, bring a finished example so you do not have to wait, and keep the steps simple. Safety comes first, so never use dangerous materials, and get adult approval for any demonstration that involves heat, sharp tools or chemicals.\n\nYour task: (1) Name the five kinds of informative speeches. (2) List five principles of informing well. (3) Plan a short demonstration speech with five steps.\n\nFlorida standards: SPC.912.C.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SPC.912.C", "script": "Welcome back. Listen, Nehemiah 8:8 says, So they read in the book in the law of God distinctly, and gave the sense, and caused them to understand the reading. Read clearly, give the sense and cause understanding. That is the goal of every informative speaker.\n\nNow watch this. An informative speech teaches. It can be about objects, people, events, processes or concepts.\n\nTo inform well, be clear. Use simple words and define terms. Be organized. Be concrete with examples, stories, comparisons and visuals. Move from the known to the unknown, like comparing the heart to a pump. Limit the main points and repeat key ideas. Show why it matters to the audience. Be accurate and cite sources. Do not try to persuade. Present the facts fairly.\n\nA demonstration speech shows how to do something. Plan steps in order. Practice with every tool. Bring a finished example. Keep it simple. Safety comes first. Get adult approval for anything that involves heat, sharp tools or chemicals.\n\nYour task is to name the kinds of informative speeches, list principles and plan a demonstration. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.1 The Informative Speech$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 14, $j$4.2 The Persuasive Speech$j$, $j${"readings": [{"title": "Acts 26 (King James Version)", "url": "/portal/bible/Acts/26"}], "body": "A persuasive speech seeks to change what listeners believe or do. The Apostle Paul gave a model when he stood before King Agrippa. Acts 26:25 records his words, I am not mad, most noble Festus; but speak forth the words of truth and soberness. At the end of the speech, Agrippa said in verse 28, Almost thou persuadest me to be a Christian. Paul spoke with courtesy, truth and conviction.\n\nPersuasive speeches address three kinds of questions. A question of fact asks whether something is true, such as, Is the local water supply safe? A question of value asks whether something is good or bad, right or wrong, such as, Is service to others more important than personal comfort? A question of policy asks what should be done, such as, Should our school start a tutoring program? A persuasive speech needs a clear claim, called a thesis, such as, Our school should start a peer tutoring program.\n\nAudiences differ in how they feel. A favorable audience agrees already and needs to be motivated. A neutral audience has not decided and needs good reasons. A hostile audience disagrees, so the speaker should find common ground, show respect and aim for modest movement, not instant conversion.\n\nA strong case has evidence and reasoning. State the problem and show that it matters. Offer a solution and show that it works and is practical. Support each claim with facts, examples and expert testimony. Address the main objection fairly and answer it. One common order is Monroe's Motivated Sequence, with five steps: get attention, show the need, satisfy the need with a solution, help listeners visualize the results, and end with a call to action. A call to action tells listeners exactly what to do, such as signing a petition, volunteering on a date or changing a habit, and it should be specific and reasonable.\n\nPersuasion must be ethical. Do not exaggerate, scare listeners with false claims, or manipulate. Respect the freedom of the audience to decide. Paul wrote in 2 Corinthians 4:2 about renouncing the hidden things of dishonesty, and commending ourselves to every man's conscience in the sight of God. Choose a topic that is real, appropriate and age suitable, and avoid topics that require sharing private details about other people.\n\nYour task: (1) Tell the difference between questions of fact, value and policy. (2) Write a thesis for a persuasive speech. (3) List the five steps of Monroe's Motivated Sequence.\n\nFlorida standards: SPC.912.C.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SPC.912.C", "script": "Welcome back. Listen, Acts 26:25 records Paul's words, I am not mad, most noble Festus; but speak forth the words of truth and soberness. And Agrippa said in verse 28, Almost thou persuadest me to be a Christian. Paul spoke with courtesy, truth and conviction.\n\nNow watch this. A persuasive speech seeks to change what listeners believe or do. A question of fact asks, is it true? A question of value asks, is it good or right? A question of policy asks, what should be done? State a clear thesis, such as, our school should start a peer tutoring program.\n\nKnow your audience. Favorable audiences need motivation. Neutral audiences need reasons. Hostile audiences need common ground and respect.\n\nBuild a strong case. Show the problem. Offer a solution that works. Support claims with evidence. Answer the main objection fairly. Monroe's Motivated Sequence has five steps: attention, need, satisfaction, visualization and action. A call to action should be specific and reasonable.\n\nPersuasion must be ethical. No exaggeration, false fear or manipulation. Respect the listener's freedom to decide.\n\nYour task is to tell the types of questions apart, write a thesis and list the five steps. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.2 The Persuasive Speech$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 15, $j$4.3 Ceremonial and Special Occasion Speeches$j$, $j${"readings": [{"title": "Romans 12 (King James Version)", "url": "/portal/bible/Romans/12"}], "body": "Not every speech informs or argues. Many speeches mark an occasion and bring people together. Romans 12:15 says, Rejoice with them that do rejoice, and weep with them that weep. Special occasion speeches help communities celebrate, honor and grieve.\n\nSeveral types are common. A speech of introduction presents a speaker to an audience. It should be short, usually under a minute or two. State the speaker's name and topic correctly, tell why the speaker is qualified, build interest, and then step aside. Ask for the correct pronunciation and the latest title ahead of time. A speech of welcome greets guests and makes them feel at home. A speech of tribute honors a person or group, such as a retiring teacher, a pastor or a team. A toast is a very short statement to honor a person or an event, often at a banquet, and it is given with a nonalcoholic drink at school and church events. A speech of presentation gives an award, telling what the award is and why the winner earned it. A speech of acceptance receives an award with gratitude and humility, thanking those who helped. A commemorative speech celebrates an anniversary, an event or a historic person. A eulogy honors someone who has died, with comfort, memory and hope, and is shared with tenderness and care. A graduation or commencement address inspires those moving into a new season. A devotional or a brief inspirational message encourages a group.\n\nSeveral principles help. Know the occasion and honor it. Be brief, since occasion speeches are often short. Be sincere, and speak from the heart with real stories. Be positive and appropriate, and avoid inside jokes that exclude people. Use vivid language and short stories to bring the person or event to life. Keep your focus on the honoree and not on yourself. Proverbs 27:2 says, Let another man praise thee, and not thine own mouth. Prepare, even when the speech is short, because a rambling tribute can spoil a good moment.\n\nWhen you have to speak without much notice, use a simple frame such as past, present and future, or three words that describe the honoree with a brief story for each.\n\nYour task: (1) Name five kinds of special occasion speeches. (2) Give three principles for tribute speaking. (3) Outline a one minute tribute to someone you admire.\n\nFlorida standards: SPC.912.C.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SPC.912.C", "script": "Welcome back. Listen, Romans 12:15 says, Rejoice with them that do rejoice, and weep with them that weep. Special occasion speeches help communities celebrate, honor and grieve.\n\nNow watch this. A speech of introduction is short. State the name and topic correctly, tell why the speaker is qualified, build interest and step aside. A speech of welcome makes guests feel at home. A tribute honors a person or group. A toast is very short and uses a nonalcoholic drink at school and church events. A presentation gives an award. An acceptance receives an award with gratitude. A commemorative speech celebrates an event. A eulogy honors someone who has died with comfort, memory and hope.\n\nPrinciples. Honor the occasion. Be brief. Be sincere. Be positive and avoid inside jokes. Use vivid language and short stories. Keep the focus on the honoree. Proverbs 27:2 says, Let another man praise thee, and not thine own mouth. Prepare, even when the speech is short.\n\nIf you must speak with little notice, use past, present and future, or three words with a story for each.\n\nYour task is to name types, give principles and outline a one minute tribute. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.3 Ceremonial and Special Occasion Speeches$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 16, $j$4.4 Storytelling and Narrative$j$, $j${"readings": [{"title": "Luke 15 (King James Version)", "url": "/portal/bible/Luke/15"}], "body": "Stories are one of the oldest and strongest ways to communicate. Jesus used stories again and again. In Luke 15:4 He asked, What man of you, having an hundred sheep, if he lose one of them, doth not leave the ninety and nine in the wilderness, and go after that which is lost, until he find it? His parables made truth easy to see and remember. A well chosen story can open a speech, illustrate a point or close with power.\n\nA good story has certain parts. The setting tells who, where and when. The characters are the people the audience can care about. The conflict is the problem or struggle that creates tension. The rising action builds through events that increase interest. The climax is the turning point. The resolution shows how it ends and what changed. A story also has a point. Ask, what do I want the audience to take away? If a story does not support the message, leave it out.\n\nTo tell a story well, start close to the action and skip long background. Use specific details, such as the smell of rain on hot pavement or the sound of a screen door, instead of vague words. Use dialogue, speaking in the voices of characters in a simple way. Show feelings through actions. Vary your voice, pace and pauses, slowing for the climax. Keep it as short as it can be and still be clear. Practice it aloud so it sounds natural.\n\nStories should be true, or clearly identified as an illustration or a fictional example. Do not invent a personal story and present it as real. Respect the privacy of others, and ask permission before sharing a story about a family member or friend, especially one that is painful. A personal narrative, which is a true story from your own life, builds trust when it is honest and shows what you learned. A testimony in a faith setting follows the same idea: share what God has done, with truth and humility.\n\nFamous speakers have used story and vivid language to move nations. Martin Luther King Jr. in 1963 used repeated phrases and images in his address in Washington, DC. Abraham Lincoln in 1863 spoke fewer than three hundred words at Gettysburg, and the speech is remembered for its clear and moving language.\n\nYour task: (1) Name the parts of a story. (2) Describe four skills for telling a story well. (3) Outline a true story from your life that makes a point.\n\nFlorida standards: SPC.912.C.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SPC.912.C", "script": "Welcome back. Listen, Luke 15:4 says, What man of you, having an hundred sheep, if he lose one of them, doth not leave the ninety and nine in the wilderness, and go after that which is lost, until he find it? Jesus used stories again and again. His parables made truth easy to see and remember.\n\nNow watch this. A story has a setting, characters, conflict, rising action, a climax and a resolution. It also has a point. If the story does not support your message, leave it out.\n\nTell it well. Start close to the action. Use specific details. Use simple dialogue. Show feelings through actions. Vary your voice and slow down for the climax. Keep it short. Practice aloud.\n\nStories must be true, or clearly labeled as illustrations. Never invent a personal story and call it real. Respect privacy and ask permission before sharing a story about someone else, especially a painful one. A personal narrative builds trust when it is honest. A testimony shares what God has done, with truth and humility.\n\nLincoln at Gettysburg in 1863 spoke fewer than three hundred words, and it is remembered for clear and moving language.\n\nYour task is to name story parts, describe skills and outline a true story. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.4 Storytelling and Narrative$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 4, $j$Assessment 4: Types of Speeches$j$, $j${"prompt": "Write a report of at least 250 words and include planning work for three kinds of speeches. Use complete sentences and label each part. Nehemiah 8:8 says, So they read in the book in the law of God distinctly, and gave the sense, and caused them to understand the reading.\n\nPart 1: Informative. Name the five kinds of informative speeches. Choose a topic and write a specific purpose, a central idea and three main points. Explain two ways you will make the topic clear and concrete.\nPart 2: Persuasive. Tell the difference between questions of fact, value and policy. Write a thesis for a persuasive speech on a school or community issue. Outline the five steps of Monroe's Motivated Sequence for it, and write a specific call to action.\nPart 3: Ceremonial. Choose a special occasion (introduction, tribute, welcome or presentation) and write a short speech of at least 100 words for it. Explain how you will keep the focus on the honoree.\nPart 4: Storytelling. Outline a true story with setting, characters, conflict, climax and resolution, and state its point. Explain how you will respect the privacy of anyone in the story.\nPart 5: Ethics and faith. Explain how a speaker can persuade honestly and respectfully. Apply Acts 26:25 and Romans 12:15 to the way a speaker serves an audience.", "rubric": "100 points. Part 1: 20 points. Part 2: 25 points. Part 3: 15 points. Part 4: 20 points. Part 5: 15 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 4: Types of Speeches$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 4, $j$Discussion 4: The Power of a Story$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes a speech, sermon or story that stayed with you and why, (2) explains in your own words the difference between informing and persuading, (3) explains how a speaker can use stories and honest persuasion to serve people and honor God, and (4) connects your answer to Nehemiah 8:8, Acts 26:25 or Luke 15:4. Then write a respectful reply of at least 40 words to another student's post, or answer this question: What makes a tribute speech sincere? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 4: The Power of a Story$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 16, $j$Check 4.1: The Informative Speech$j$, $j${"questions": [{"q": "The main goal of an informative speech is to:", "options": ["Teach and cause understanding", "Sell a product", "Win an argument", "Entertain only"]}, {"q": "Comparing the heart to a pump is an example of:", "options": ["Moving from the known to the unknown", "Plagiarism", "Jargon", "A new main point"]}, {"q": "A speech explaining how a bill becomes a law is about a:", "options": ["Person", "Process", "Place", "Object"]}, {"q": "Before a demonstration that uses heat or sharp tools, a student should:", "options": ["Get adult approval and plan for safety", "Rush through", "Skip the plan", "Invite the audience to try it"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: The Informative Speech$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,0,1,0}'::int[], array[$j$Informing means helping people understand.$j$,$j$A familiar comparison makes a new idea clear.$j$,$j$It explains steps in a process.$j$,$j$Safety comes first.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: The Informative Speech$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 17, $j$Check 4.2: The Persuasive Speech$j$, $j${"questions": [{"q": "The question, Should our school start a tutoring program? is a question of:", "options": ["Policy", "Fact", "Definition", "Value"]}, {"q": "The one sentence claim a persuasive speech defends is the:", "options": ["Handout", "Thesis", "Transition", "Citation"]}, {"q": "When facing a hostile audience, a speaker should:", "options": ["Avoid eye contact", "Insult them", "Shout", "Find common ground and show respect"]}, {"q": "In Monroe's Motivated Sequence, the last step is:", "options": ["Action", "Attention", "Visualization", "Need"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: The Persuasive Speech$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,3,0}'::int[], array[$j$Policy asks what should be done.$j$,$j$The thesis states the position.$j$,$j$Respect and common ground open minds.$j$,$j$The speech ends with a specific call to action.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: The Persuasive Speech$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 18, $j$Check 4.3: Ceremonial and Special Occasion Speeches$j$, $j${"questions": [{"q": "A speech that presents a speaker to an audience is a speech of:", "options": ["Tribute", "Acceptance", "Introduction", "Welcome"]}, {"q": "A good speech of introduction should be:", "options": ["About the introducer", "Short, accurate and interesting", "Longer than the main speech", "Full of jokes"]}, {"q": "In a tribute, the focus should be on:", "options": ["The honoree", "The speaker", "The weather", "The sound system"]}, {"q": "A speech that honors someone who has died is a:", "options": ["Eulogy", "Toast", "Commencement address", "Presentation"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: Ceremonial and Special Occasion Speeches$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,1,0,0}'::int[], array[$j$It introduces the speaker.$j$,$j$The introducer should step aside quickly.$j$,$j$A tribute honors someone else.$j$,$j$A eulogy offers comfort and remembrance.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: Ceremonial and Special Occasion Speeches$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 19, $j$Check 4.4: Storytelling and Narrative$j$, $j${"questions": [{"q": "The turning point of a story is the:", "options": ["Resolution", "Setting", "Climax", "Title"]}, {"q": "A story used in a speech should:", "options": ["Embarrass someone", "Be invented as if real", "Be as long as possible", "Support the point of the message"]}, {"q": "Which makes a story vivid?", "options": ["Specific details", "Reading a script", "Vague words", "Long background"]}, {"q": "Before telling a painful story about a friend or relative, a speaker should:", "options": ["Post it first", "Ask permission and respect their privacy", "Share it without asking", "Add details to make it better"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: Storytelling and Narrative$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,0,1}'::int[], array[$j$The climax is the high point of tension.$j$,$j$Every story needs a purpose.$j$,$j$Specific details help listeners picture it.$j$,$j$Respect for others comes first.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: Storytelling and Narrative$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 20, $j$Unit Quiz 4: Types of Speeches$j$, $j${"questions": [{"q": "A speech explaining how a hurricane forms is mainly:", "options": ["A toast", "A eulogy", "Informative", "Persuasive"]}, {"q": "A thesis in a persuasive speech is:", "options": ["The main claim the speaker defends", "A greeting", "A list of sources", "A story"]}, {"q": "The question, Is honesty more important than popularity? is a question of:", "options": ["Fact", "Policy", "Value", "Time"]}, {"q": "A call to action should be:", "options": ["Specific and reasonable", "Hidden", "Vague", "Impossible"]}, {"q": "A very short statement to honor a person or event at a banquet is a:", "options": ["Demonstration", "Eulogy", "Commencement address", "Toast"]}, {"q": "In a speech of introduction, the introducer should:", "options": ["Talk for ten minutes", "Step aside after building interest", "Argue with the speaker", "Give the main speech"]}, {"q": "A story in a speech should be:", "options": ["Very long", "Unrelated to the point", "Invented and called real", "True, or clearly labeled as an illustration"]}, {"q": "Jesus taught truth in Luke 15 by using:", "options": ["A parable", "A slide show", "A chart", "A debate"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: Types of Speeches$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,2,0,3,1,3,0}'::int[], array[$j$It teaches how a process works.$j$,$j$The thesis is the position.$j$,$j$Value asks what is good or right.$j$,$j$Listeners need to know what to do.$j$,$j$A toast is brief and warm.$j$,$j$The introduction is brief.$j$,$j$Honesty applies to stories.$j$,$j$Parables are stories that make truth memorable.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: Types of Speeches$j$ on conflict (item_id) do nothing;
